        assert!(runtime_only_markup.contains(r#"data-host-action="remove"><svg"#));
        assert!(runtime_only_markup.contains(r#"data-declared="false""#));

        let mut pending_update = host_with_backups("hsb8", 1_700_000_100, vec![]);
